import { DesignComponentsFolder } from "@/components/custom/blocks/DesignComponentsFolder";

export default function Showcase() {
  return <DesignComponentsFolder />;
}

"use client";

import React, { useState, useEffect } from "react";
import {
  ArrowRight,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { springLinear } from "./motion-curves";

// Springs, drawn as CSS `linear()` curves: the fan-out, the retract into the
// folder, and the lift under the pointer (the move and the scale).
const FAN_OUT = springLinear({ stiffness: 90, damping: 14 });
const RETRACT = springLinear({ stiffness: 110, damping: 15 });
const HOVER_MOVE = springLinear({ stiffness: 500, damping: 25 });
const HOVER_SCALE = springLinear({ stiffness: 550, damping: 30 });
const HOVER_LAYER = "0.3s cubic-bezier(0.25, 0.1, 0.35, 1)";
const timing = (spring: { duration: number; easing: string }, delay = 0) =>
  `${spring.duration}ms ${spring.easing}${delay ? ` ${delay}s` : ""}`;

/** Where a card starts (tucked in the folder), where it fans out to, and how it lifts. */
interface FanCard {
  initX: number;
  initY: number;
  rotate: number;
  delay: number;
  zIndex: number;
  hoverScale: number;
  hoverRotate: number;
}

// Folder silhouette in the 660×310 viewBox: tab on the left, body below.
const FOLDER_PATH = `
  M -8 8
  C -8 3, -3 0, 8 0
  L 330 0
  C 347 0, 360 25, 372 45
  C 380 58, 392 68, 408 68
  L 638 68
  C 644 68, 648 72, 648 80
  L 620 302
  C 620 307, 616 310, 610 310
  L 30 310
  C 24 310, 20 307, 20 302
  Z
`;

export interface DesignComponentsFolderProps {
  color?: string;
  className?: string;
  disableLinks?: boolean;
  /**
   * The element used for links. Defaults to a plain `a`, so this component works
   * in any React app with no adaptation. In Next.js, pass `next/link` to keep
   * client-side navigation and prefetching: `linkComponent={Link}`.
   */
  linkComponent?: React.ElementType;
}

export function DesignComponentsFolder({
  color,
  className,
  disableLinks = false,
  linkComponent: Link = "a",
}: DesignComponentsFolderProps) {
  const [isInView, setIsInView] = useState(false);
  const [retractedIndex, setRetractedIndex] = useState<number | null>(null);

  const getAccentColor = (col?: string) => {
    if (!col || col === "primary" || col === "default") return undefined;
    const presets: Record<string, string> = {
      indigo: "#6366f1",
      rose: "#f43f5e",
      emerald: "#10b981",
      zinc: "#18181b",
    };
    return presets[col] || col;
  };

  const resolvedColor = getAccentColor(color);
  const customStyle: React.CSSProperties = resolvedColor
    ? ({ "--primary": resolvedColor } as React.CSSProperties)
    : {};

  // The retract loop runs only while the folder is on screen: off screen it
  // would keep re-rendering every card for nothing. It picks up at the next
  // card when the reader scrolls back.
  const [onScreen, setOnScreen] = useState(false);
  const nextCardRef = React.useRef(0);

  useEffect(() => {
    if (!isInView || !onScreen) return;

    let interval = 0;
    let bringBack = 0;
    // Start auto loop 2 seconds after the entrance fan-out (or the return).
    const startTimer = window.setTimeout(() => {
      interval = window.setInterval(() => {
        // Retract card into folder
        setRetractedIndex(nextCardRef.current);

        // Bring card back out to visible state after 900ms
        bringBack = window.setTimeout(() => {
          setRetractedIndex(null);
          nextCardRef.current = (nextCardRef.current + 1) % 8;
        }, 900);
      }, 2500);
    }, 2000);

    // Every timer is cleared here — the interval and the pending bring-back
    // included — so leaving the screen or unmounting stops the loop cold.
    return () => {
      window.clearTimeout(startTimer);
      window.clearInterval(interval);
      window.clearTimeout(bringBack);
      setRetractedIndex(null);
    };
  }, [isInView, onScreen]);

  // The stage reports when it is on screen; the first time also starts the fan-out.
  const stageRef = React.useRef<HTMLDivElement>(null);
  useEffect(() => {
    const el = stageRef.current;
    if (!el) return;
    const io = new IntersectionObserver(([entry]) => {
      if (!entry) return;
      if (entry.isIntersecting) {
        setIsInView(true);
        setOnScreen(true);
      } else setOnScreen(false);
    });
    io.observe(el);
    return () => io.disconnect();
  }, []);

  // The card under a (non-touch) pointer lifts, turns and rises above the rest.
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);

  // Fan-out: each card starts small and hidden down in the folder and springs
  // out to its place after its own delay; the retract loop springs one back
  // in. A lifted card springs to its hover pose, and settles back the way it
  // fanned out — its delay included.
  const cardMotion = (index: number, card: FanCard) => {
    const state = !isInView ? "hidden" : retractedIndex === index ? "retracted" : "visible";
    const tucked = state !== "visible";
    const hovered = hoveredIndex === index;
    const settle = state === "visible" ? timing(FAN_OUT, card.delay) : timing(RETRACT);
    const move = hovered ? timing(HOVER_MOVE) : settle;
    return {
      style: {
        translate: `${tucked ? card.initX : 0}px ${hovered ? -10 : tucked ? card.initY : 0}px`,
        scale: hovered ? card.hoverScale : tucked ? 0.2 : 1,
        rotate: `${hovered ? card.hoverRotate : tucked ? 0 : card.rotate}deg`,
        opacity: tucked ? 0 : 1,
        zIndex: hovered ? 40 : card.zIndex,
        transition: [
          `translate ${move}`,
          `rotate ${move}`,
          `scale ${hovered ? timing(HOVER_SCALE) : settle}`,
          `opacity ${settle}`,
          `z-index ${hovered ? HOVER_LAYER : settle}`,
        ].join(", "),
      } as React.CSSProperties,
      onPointerEnter: (e: React.PointerEvent) => {
        if (e.pointerType !== "touch") setHoveredIndex(index);
      },
      onPointerLeave: () => setHoveredIndex((current) => (current === index ? null : current)),
    };
  };

  return (
    <section style={customStyle} className={cn("relative w-full py-8 md:py-16 select-none flex justify-center items-center", className)}>
      {/* 
        Full Width Responsive Stage with Scale Wrapper to ensure cards shrink smoothly on mobile/small screens
      */}
      <div className="w-full flex justify-center items-center px-1 sm:px-0">
        <div
          ref={stageRef}
          className="relative w-full min-[494px]:w-[70%] sm:w-full max-w-[960px] mx-auto h-[380px] min-[450px]:h-[440px] min-[550px]:h-[500px] min-[620px]:h-[540px] sm:h-[580px] md:h-[660px] lg:h-[700px] flex items-end justify-center origin-bottom scale-[0.88] min-[400px]:scale-[0.94] min-[500px]:scale-[0.98] sm:scale-100 transition-all duration-300"
        >
          {/* CARDS FANNING OUT & AUTOMATIC SEQUENTIAL RETRACTING LOOP */}
          <div className="absolute inset-0 z-10 pointer-events-none">
            <div className="relative w-full h-full pointer-events-auto">

            {/* Card 0: Calendar (calendar.tsx) -> Indigo/Purple Tint */}
            <div
              {...cardMotion(0, { initX: 240, initY: 340, rotate: -8, delay: 0.1, zIndex: 11, hoverScale: 1.06, hoverRotate: -3 })}
              className="absolute top-[26%] sm:top-[6%] left-[6%] sm:left-[10%] md:left-[14%] lg:left-[16%] w-[130px] sm:w-[210px] md:w-[280px] lg:w-[320px] h-[105px] sm:h-[165px] md:h-[210px] lg:h-[235px] rounded-2xl overflow-hidden shadow-2xl border border-indigo-500/30 cursor-pointer group bg-gradient-to-br from-indigo-500/10 via-card to-purple-500/10 p-2.5 sm:p-4 flex flex-col justify-between"
            >
              <Link href={disableLinks ? "#" : "/docs/nextjs/calendar"} onClick={disableLinks ? (e: React.MouseEvent) => e.preventDefault() : undefined} className="w-full h-full flex flex-col justify-between">
                {/* Top: Miniature Illustration Container */}
                <div className="w-full flex-1 rounded-xl border border-indigo-500/20 bg-background/80 p-2 sm:p-2.5 flex flex-col justify-between overflow-hidden relative mb-1.5 sm:mb-2 group-hover:border-indigo-500/60 transition-colors">
                  <div className="flex items-center justify-between border-b border-border/50 pb-1.5 mb-1.5 shrink-0">
                    <div className="flex items-center gap-1">
                      <span className="size-1.5 rounded-full bg-rose-500/80 inline-block" />
                      <span className="size-1.5 rounded-full bg-amber-500/80 inline-block" />
                      <span className="size-1.5 rounded-full bg-emerald-500/80 inline-block" />
                    </div>
                    <span className="text-[9px] font-mono text-muted-foreground/70 truncate max-w-[120px] font-semibold">calendar.tsx</span>
                    <div className="size-2 rounded-full bg-indigo-500/40" />
                  </div>

                  <div className="flex-1 flex flex-col justify-center items-center relative overflow-hidden w-full">
                    <div className="w-full p-1.5 rounded-xl bg-card border border-indigo-500/20 space-y-1 my-auto text-[6.5px]">
                      <div className="flex items-center justify-between border-b border-border/40 pb-0.5 px-0.5">
                        <div className="flex items-center gap-1">
                          <span className="size-1.5 rounded-full bg-indigo-500 animate-pulse" />
                          <span className="font-extrabold text-[7.5px] text-foreground">August 2026</span>
                        </div>
                        <div className="flex items-center gap-0.5 text-muted-foreground text-[6px]">
                          <span className="size-3 rounded bg-muted/60 border border-border flex items-center justify-center font-semibold">‹</span>
                          <span className="size-3 rounded bg-muted/60 border border-border flex items-center justify-center font-semibold">›</span>
                        </div>
                      </div>
                      <div className="grid grid-cols-7 gap-0.5 font-extrabold text-muted-foreground/70 text-center text-[5.5px] uppercase">
                        <span>Su</span><span>Mo</span><span>Tu</span><span>We</span><span>Th</span><span>Fr</span><span>Sa</span>
                      </div>
                      <div className="grid grid-cols-7 gap-0.5 text-center font-semibold text-[6px] items-center">
                        <span className="text-muted-foreground/30 py-0.5">30</span>
                        <span className="text-muted-foreground/30 py-0.5">31</span>
                        <span className="py-0.5 rounded text-foreground">1</span>
                        <span className="py-0.5 rounded text-foreground">2</span>
                        <span className="py-0.5 rounded text-foreground">3</span>
                        <span className="py-0.5 rounded text-foreground">4</span>
                        <span className="py-0.5 rounded text-foreground">5</span>
                        <span className="py-0.5 rounded-l-md bg-indigo-600 text-white font-semibold">14</span>
                        <span className="py-0.5 bg-indigo-500/20 text-indigo-600 font-extrabold">15</span>
                        <span className="py-0.5 bg-indigo-500/20 text-indigo-600 font-extrabold">16</span>
                        <span className="py-0.5 rounded-r-md bg-indigo-600 text-white font-semibold">17</span>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Bottom: Card Info & Arrow */}
                <div className="flex items-center justify-between pt-1 shrink-0">
                  <div className="min-w-0 pr-1">
